%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;
scuts_path = 'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts';
Cutfitfile = fullfile(scuts_path,'NG_FFCutsFits.mat');

if ~exist('NG_FFCutsFits','var')
    ld = load(Cutfitfile);
    NG_FFCutsFits = ld.fit_src_struc;
end
fit_res_field = 'all_fit_par';
separate_fig  = false; % if true, detach figures from live script

%%

[S_op11Ei200,J_op11Ei200,Gam_op11Ei200,S_op11Ei200q] = extract_fit_par( ...
    NG_FFCutsFits.(['Ei200_off110NGminFF_',fit_res_field]));
[S_op11Ei400,J_op11Ei400,Gam_op11Ei400,S_op11Ei400q] = extract_fit_par( ...
    NG_FFCutsFits.(['Ei400_off110NGminFF_',fit_res_field]));
[S_op11Ei800,J_op11Ei800,Gam_op11Ei800,S_op11Ei800q] = extract_fit_par( ...
    NG_FFCutsFits.(['Ei800_off110NGminFF_',fit_res_field]));

proj110minFF = NG_FFCutsFits.Ei200_off110NGminFF.data.proj;


[S_maEi800,J_maEi800,Gam_maEi800,S_maEi800q] = extract_fit_par( ...
    NG_FFCutsFits.(['Ei800_off200NGmaxFF_',fit_res_field]));
proj200maxFF = NG_FFCutsFits.Ei200_off200NGmaxFF.data.proj;

plot_fp(separate_fig,'min FF change for low dE max FF for Ei800', ... %[output:group:7b4e549a] %[output:5dafb14b] %[output:147270c5] %[output:870c9727]
    [S_op11Ei200,S_op11Ei400,S_op11Ei800,S_maEi800], ... %[output:5dafb14b] %[output:147270c5] %[output:870c9727]
    [J_op11Ei200,J_op11Ei400,J_op11Ei800,J_maEi800], ... %[output:5dafb14b] %[output:147270c5] %[output:870c9727]
    [Gam_op11Ei200,Gam_op11Ei400,Gam_op11Ei800,Gam_maEi800]); %[output:group:7b4e549a] %[output:5dafb14b] %[output:147270c5] %[output:870c9727]
%%
bg_dataEi200 = extract_bg_par(NG_FFCutsFits.(['Ei200_off110NGminFF_',fit_res_field]),1);
bg_dataEi400 = extract_bg_par(NG_FFCutsFits.(['Ei400_off110NGminFF_',fit_res_field]),1);
bg_dataEi800mi = extract_bg_par(NG_FFCutsFits.(['Ei800_off110NGminFF_',fit_res_field]),1);
bg_dataEi800ma = extract_bg_par(NG_FFCutsFits.(['Ei800_off200NGmaxFF_',fit_res_field]),1);

plot_fp(separate_fig,'line-q fit bg for different Ei',[], ... %[output:group:981d7022] %[output:2956d259]
    [bg_dataEi200,bg_dataEi400,bg_dataEi800mi,bg_dataEi800ma]) %[output:group:981d7022] %[output:2956d259]
%%
spp.Ei200_off110NGminNbg = NG_FFCutsFits.Ei200_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei200_off110NGminFF,@linterp_bg,bg_dataEi200);
spp.Ei200_off110NGminNbg = cut(spp.Ei200_off110NGminNbg, ... %[output:group:6bc58a26] %[output:6f0fa0a9]
    [-0.35,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0])) %[output:group:6bc58a26] %[output:6f0fa0a9]
plot(spp.Ei200_off110NGminNbg); lz 0 1; keep_figure %[output:2329b787]
%%

spp.Ei400_off110NGminNbg = NG_FFCutsFits.Ei400_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei400_off110NGminFF,@linterp_bg,bg_dataEi400);
spp.Ei400_off110NGminNbg = cut(spp.Ei400_off110NGminNbg,[-0.5,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0])) %[output:62e6fead]
plot(spp.Ei400_off110NGminNbg); lz 0 1; keep_figure %[output:992c6b99]

spp.Ei800_off110NGminNbg = NG_FFCutsFits.Ei800_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei800_off110NGminFF,@linterp_bg,bg_dataEi800mi);
spp.Ei800_off110NGminNbg = cut(spp.Ei800_off110NGminNbg, ...
    [-0.5,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0]));
plot(spp.Ei800_off110NGminNbg); lz 0 1; keep_figure %[output:648e0eac]
%%

spp.Ei800_off200NGmaxNbg = NG_FFCutsFits.Ei800_off200NGmaxFF - ...
    sqw_eval(NG_FFCutsFits.Ei800_off200NGmaxFF,@linterp_bg,bg_dataEi800ma);
spp.Ei800_off200NGmaxNbg = cut(spp.Ei800_off200NGmaxNbg, ... %[output:group:3960c684] %[output:669e1754]
    [-0.5,0.005,0],[],SymopReflection('normvec',[1,1,0],'offset',[2,0,0])) %[output:group:3960c684] %[output:669e1754]
plot(spp.Ei800_off200NGmaxNbg); lz 0 0.1; keep_figure %[output:569ffc81]
%%


%%
cuts_ranges = containers.Map();
cuts_ranges('Ei200_off110NGminNbg')  = [0;110];
cuts_ranges('Ei400_off110NGminNbg') = [110;170];
cuts_ranges('Ei800_off110NGminNbg') = [170;250];
cuts_ranges('Ei800_off200NGmaxNbg') = [250;390];

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_ranges,[-0.5,0.005,0],false); %[output:318ef7cb]
data_ranges = cuts_ranges.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
%save('NG_0p5_0p5_0_data','pan_data');
fh.UserData = w2.data;
%%
gamma=10;Seff0=0.7917;

J0=39; J1=35;
correct_ff = 1;
gap = 0;    %
init_fg_param = [correct_ff,8,gamma,Seff0,  0,   J0, J1,  0,  0,  0];

kk = tobyfit(spp.Ei800_off200NGmaxNbg);
kk = kk.set_fun(@sqw_iron);
hkl_proj = spp.Ei800_off200NGmaxNbg.data.proj;

%init_fg_params = [coffect_ff,T,gamma,Seff, gap, J0, J1, J2, J3, J4];
free_sw_param  =  [0          0, 1   ,1   , 0,    1, 1,   0,  0,  0];

kk = kk.set_pin({init_fg_param,hkl_proj});
kk = kk.set_free(free_sw_param);


%kk = kk.set_bfun (@linear_bg1D); % set_bfun sets the background functions
%
%bg_param = init_bg_param(valid);
%kk = kk.set_bpin (bg_param);  % initial background constant and gradient
%kk = kk.set_bfree (bfree);

kk = kk.set_options('list',2);


[fit_obj,fit_par] = kk.fit(); %[output:8e7bff83] %[output:74bb272e]
%%

plot(spp.Ei800_off200NGmaxNbg); lz 0 0.1;keep_figure; %[output:569eea8e]
plot(fit_obj); lz 0 0.1;keep_figure; %[output:675a186a]
%[fit_obj,fit_par] = kk.simulate();
%%
if ~exist('magi','var')
    magi = MagneticIons();
end
spp.Ei200_off110NGminNbg= magi.correct_mag_ff(spp.Ei200_off110NGminNbg);
plot(spp.Ei200_off110NGminNbg); lz 0 1;keep_figure; %[output:76e25368]

spp.Ei400_off110NGminNbg = magi.correct_mag_ff(spp.Ei400_off110NGminNbg);
plot(spp.Ei400_off110NGminNbg); lz 0 1; keep_figure %[output:2160d809]

spp.Ei800_off110NGminNbg = magi.correct_mag_ff(spp.Ei800_off110NGminNbg);
plot(spp.Ei800_off110NGminNbg); lz 0 1; keep_figure %[output:515e4bc4]

spp.Ei800_off200NGmaxNbg = magi.correct_mag_ff(spp.Ei800_off200NGmaxNbg);
plot(spp.Ei800_off200NGmaxNbg); lz 0 1; keep_figure %[output:552bc267]

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_ranges,0.01,0.5,false); %[output:3192a9ef] %[output:486800d7]
data_ranges = cuts_ranges.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);


